package dev.growthworkbench.app;

import androidx.test.ext.junit.runners.AndroidJUnit4;
import androidx.test.platform.app.InstrumentationRegistry;
import androidx.core.content.FileProvider;
import android.content.Context;
import android.content.Intent;
import android.net.Uri;
import android.webkit.WebResourceRequest;
import android.webkit.WebResourceResponse;
import org.json.*;
import org.junit.Test;
import org.junit.runner.RunWith;
import java.io.*;
import java.util.*;
import static org.junit.Assert.*;

/** Emulator/device instrumentation. These tests invoke real Keystore, SQLCipher and private file IO. */
@RunWith(AndroidJUnit4.class)
public class NativeIntegrationTest {
 private Context context(){return InstrumentationRegistry.getInstrumentation().getTargetContext();}
 @Test public void sqliteCommitPersistsAndRejectsStaleRevision() throws Exception {
  Context context=context();NativeRepository repository=new NativeRepository(context,new NativeCredentials(context));String account="instrumentation-"+UUID.randomUUID();JSONObject descriptor=repository.open(account);assertEquals("3.53.4",descriptor.getString("sqliteVersion"));assertEquals("wal",descriptor.getString("journalMode"));String handle=descriptor.getString("handle");JSONObject snapshot=repository.snapshot(handle);JSONObject state=snapshot.getJSONObject("state");state.getJSONObject("cursors").put("proof","committed");repository.commit(handle,snapshot.getLong("revision"),state);
  try{repository.commit(handle,snapshot.getLong("revision"),state);fail("stale native revision must fail");}catch(IllegalStateException expected){assertEquals("STALE_NATIVE_REVISION",expected.getMessage());}
  repository.close(handle);String reopened=repository.open(account).getString("handle");assertEquals("committed",repository.snapshot(reopened).getJSONObject("state").getJSONObject("cursors").getString("proof"));repository.close(reopened);
 }
 @Test public void keystoreCiphertextSurvivesAdapterRestartAndContainsNoToken() throws Exception {
  Context context=context();String key="instrumentation-"+UUID.randomUUID(),token="private-device-token-"+UUID.randomUUID();NativeCredentials first=new NativeCredentials(context);first.set(key,token);File file=new File(NativeIO.directory(context,"credentials-v2"),NativeIO.hash(key)+".json");assertFalse(NativeIO.json(file).toString().contains(token));assertEquals(token,new NativeCredentials(context).get(key));first.set(key,null);assertNull(first.get(key));
 }
 private Uri source(byte[] data) throws Exception {File directory=new File(context().getCacheDir(),"outgoing");directory.mkdirs();File file=new File(directory,"fixture-"+UUID.randomUUID()+".pdf");try(FileOutputStream stream=new FileOutputStream(file)){stream.write(data);}return FileProvider.getUriForFile(context(),context().getPackageName()+".fileprovider",file);}
 @Test public void shareCopyPersistsBeforeAckAndFencesAccountReplay() throws Exception {
  Context context=context();NativeFiles files=new NativeFiles(context);NativeShares shares=new NativeShares(context,files,new NativeCredentials(context));byte[] bytes="actual source bytes".getBytes(java.nio.charset.StandardCharsets.UTF_8);String id=UUID.randomUUID().toString();Intent intent=new Intent(Intent.ACTION_SEND).setType("application/pdf").putExtra(Intent.EXTRA_STREAM,source(bytes)).putExtra(Intent.EXTRA_TEXT,"private share text");shares.receive(intent,id);shares.receive(intent,id);JSONObject receipt=null;JSONArray pending=shares.pending();int count=0;for(int i=0;i<pending.length();i++)if(id.equals(pending.getJSONObject(i).getString("deliveryId"))){receipt=pending.getJSONObject(i);count++;}assertEquals(1,count);assertNotNull(receipt);assertEquals("ready",receipt.getString("status"));JSONObject ref=receipt.getJSONArray("files").getJSONObject(0);assertArrayEquals(bytes,files.source(ref.getString("token"),0,bytes.length));assertEquals("original-account",shares.claim(id,"original-account"));try{shares.claim(id,"different-account");fail("must not rebind incoming material");}catch(SecurityException expected){}shares.acknowledge(id,"original-account");assertArrayEquals(bytes,files.source(ref.getString("token"),0,bytes.length));
 }
 @Test public void inaccessibleUriLeavesReshareReceipt() throws Exception {Context context=context();NativeShares shares=new NativeShares(context,new NativeFiles(context),new NativeCredentials(context));String id=UUID.randomUUID().toString();shares.receive(new Intent(Intent.ACTION_SEND).setType("application/pdf").putExtra(Intent.EXTRA_STREAM,Uri.parse("content://dev.growthworkbench.missing/revoked")),id);JSONArray pending=shares.pending();for(int i=0;i<pending.length();i++){JSONObject receipt=pending.getJSONObject(i);if(id.equals(receipt.getString("deliveryId"))){assertEquals("needs-reshare",receipt.getString("status"));assertTrue(receipt.getString("message").contains("重新分享"));return;}}fail("retryable receipt lost");}
 @Test public void previewServesCrossPartRangeWithoutWholeFileBridge() throws Exception {NativeFiles files=new NativeFiles(context());String account="instrumentation-"+UUID.randomUUID();files.write(account,"a",android.util.Base64.encodeToString(new byte[]{0,1,2},android.util.Base64.NO_WRAP));files.write(account,"b",android.util.Base64.encodeToString(new byte[]{3,4,5},android.util.Base64.NO_WRAP));JSONObject preview=files.preview(account,new JSONArray().put("a").put("b"),6,"video/mp4");Uri uri=Uri.parse(preview.getString("url"));WebResourceRequest request=new WebResourceRequest(){public Uri getUrl(){return uri;}public boolean isForMainFrame(){return false;}public boolean isRedirect(){return false;}public boolean hasGesture(){return false;}public String getMethod(){return "GET";}public Map<String,String> getRequestHeaders(){return Collections.singletonMap("Range","bytes=2-4");}};WebResourceResponse response=files.intercept(request);assertEquals(206,response.getStatusCode());assertEquals("bytes 2-4/6",response.getResponseHeaders().get("Content-Range"));ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(InputStream stream=response.getData()){byte[] chunk=new byte[10];int n;while((n=stream.read(chunk))!=-1)bytes.write(chunk,0,n);}assertArrayEquals(new byte[]{2,3,4},bytes.toByteArray());files.release(preview.getString("token"));assertEquals(404,files.intercept(request).getStatusCode());}
 @Test public void activeSameOriginPreviewIsRejected() throws Exception {NativeFiles files=new NativeFiles(context());String account="instrumentation-"+UUID.randomUUID();files.write(account,"active",android.util.Base64.encodeToString("<script>bad()</script>".getBytes(java.nio.charset.StandardCharsets.UTF_8),android.util.Base64.NO_WRAP));for(String mime:new String[]{"text/html","image/svg+xml","application/xhtml+xml","application/javascript"}){try{files.preview(account,new JSONArray().put("active"),22,mime);fail("active imported content must not execute in the app origin");}catch(SecurityException expected){assertEquals("UNSUPPORTED_PREVIEW_TYPE",expected.getMessage());}}}
 @Test public void onlySavedActivityStateMayRestoreDeliveryIdentity(){String first=MainActivity.deliveryIdentity(null),second=MainActivity.deliveryIdentity(null);assertNotEquals(first,second);assertEquals(first,MainActivity.deliveryIdentity(first));assertNotEquals("sender-controlled",MainActivity.deliveryIdentity("sender-controlled"));}
 @Test public void legacyAtomicBackupsRecoverJsonCredentialsAndFileRanges() throws Exception {Context context=context();String id=UUID.randomUUID().toString();File json=new File(NativeIO.directory(context,"instrumentation-v2"),id+".json");NativeIO.json(json,new JSONObject().put("proof","before-kill"));assertTrue(json.renameTo(new File(json.getPath()+".bak")));assertEquals("before-kill",NativeIO.json(json).getString("proof"));NativeCredentials credentials=new NativeCredentials(context);String key="instrumentation-backup-"+id;credentials.set(key,"recover-token");File credential=new File(NativeIO.directory(context,"credentials-v2"),NativeIO.hash(key)+".json");assertTrue(credential.renameTo(new File(credential.getPath()+".bak")));assertEquals("recover-token",new NativeCredentials(context).get(key));credentials.set(key,null);NativeFiles files=new NativeFiles(context);files.write(id,"part",android.util.Base64.encodeToString(new byte[]{7,8,9},android.util.Base64.NO_WRAP));File part=files.file(id,"part");assertTrue(part.renameTo(new File(part.getPath()+".bak")));assertEquals("CAk=",files.readStorage(id,"part",1L,2).getString("data"));}
 @Test public void ignoredReceiptCanBeRestoredWithoutDeletingOriginal() throws Exception {Context context=context();NativeFiles files=new NativeFiles(context);NativeShares shares=new NativeShares(context,files,new NativeCredentials(context));String id=UUID.randomUUID().toString();byte[] bytes=new byte[]{11,12};shares.receive(new Intent(Intent.ACTION_SEND).setType("application/pdf").putExtra(Intent.EXTRA_STREAM,source(bytes)),id);JSONObject receipt=null;JSONArray before=shares.pending();for(int i=0;i<before.length();i++)if(id.equals(before.getJSONObject(i).getString("deliveryId")))receipt=before.getJSONObject(i);assertNotNull(receipt);String token=receipt.getJSONArray("files").getJSONObject(0).getString("token");shares.dismiss(id,"original-account");JSONArray pending=shares.pending();for(int i=0;i<pending.length();i++)assertNotEquals(id,pending.getJSONObject(i).getString("deliveryId"));boolean archived=false;JSONArray all=shares.pending(true);for(int i=0;i<all.length();i++)if(id.equals(all.getJSONObject(i).getString("deliveryId")))archived=all.getJSONObject(i).getBoolean("dismissed");assertTrue(archived);assertArrayEquals(bytes,files.source(token,0,2));try{shares.restore(id,"different-account");fail("ignored material must preserve account ownership");}catch(SecurityException expected){}shares.restore(id,"original-account");assertEquals("original-account",shares.claim(id,"original-account"));shares.acknowledge(id,"original-account");assertArrayEquals(bytes,files.source(token,0,2));}
 @Test public void overlongShareCreatesActionableReceiptWithoutSilentTruncation() throws Exception {Context context=context();NativeShares shares=new NativeShares(context,new NativeFiles(context),new NativeCredentials(context));String id=UUID.randomUUID().toString();char[] characters=new char[10001];Arrays.fill(characters,'x');shares.receive(new Intent(Intent.ACTION_SEND).setType("text/plain").putExtra(Intent.EXTRA_TEXT,new String(characters)),id);JSONArray pending=shares.pending();for(int i=0;i<pending.length();i++){JSONObject receipt=pending.getJSONObject(i);if(id.equals(receipt.getString("deliveryId"))){assertEquals("needs-reshare",receipt.getString("status"));assertTrue(receipt.getString("message").contains("10000"));assertFalse(receipt.has("text"));shares.dismiss(id,"instrumentation-account");return;}}fail("overlong share must remain actionable");}
 @Test public void expiredSignedInboxInputIsRemovedAndRequiresReshare() throws Exception {Context context=context();NativeCredentials credentials=new NativeCredentials(context);NativeShares shares=new NativeShares(context,new NativeFiles(context),credentials);String id=UUID.randomUUID().toString();shares.receive(new Intent(Intent.ACTION_SEND).setType("text/plain").putExtra(Intent.EXTRA_TEXT,"阅读 https://example.com/file.pdf?signature=expire-secret"),id);credentials.set("share-content:"+id,new JSONObject().put("text","阅读 https://example.com/file.pdf?signature=expire-secret").put("expiresAt",System.currentTimeMillis()-1).toString());JSONArray pending=shares.pending();for(int i=0;i<pending.length();i++){JSONObject receipt=pending.getJSONObject(i);if(id.equals(receipt.getString("deliveryId"))){assertEquals("needs-reshare",receipt.getString("status"));assertTrue(receipt.getString("message").contains("重新分享"));assertFalse(receipt.optString("text").contains("expire-secret"));assertNull(credentials.get("share-content:"+id));assertFalse(credentials.get(NativeShareInputs.noteKey(id)).contains("expire-secret"));shares.dismiss(id,"instrumentation-account");return;}}fail("expired signed receipt must remain recoverable by re-share");}
}
